function selfCheckingNumbers(left: number, right: number): number[] {
  const out: number[] = [];
  for (let v = left; v <= right; v++) {
    const ok = String(v).split("").every(c => c !== "0" && v % Number(c) === 0);
    if (ok) out.push(v);
  }
  return out;
}

