function selfCheckingNumbers(left: number, right: number): number[] {
  const out: number[] = [];
  for (let v = left; v <= right; v++) {
    let x = v, ok = true;
    while (x > 0 && ok) {
      const d = x % 10;
      if (d === 0 || v % d !== 0) ok = false;
      x = Math.floor(x / 10);
    }
    if (ok) out.push(v);
  }
  return out;
}

